SELECT o.id, o.symbol, o.status, o.started_at, o.last_evidence_at, o.anchor_entry_price, o.best_entry_price, o.evidence_count, o.buy_count, o.watch_count, o.neutral_count, o.bearish_count, o.evidence_score, o.opportunity_health, o.five_minute_decision, o.one_hour_decision, o.execution_source, o.recommended_position_percent, o.decision_code, o.executed_at FROM crypto_ai.execution_opportunity o JOIN crypto_ai.paper_position p ON p.symbol = o.symbol AND o.executed_at BETWEEN p.opened_at - INTERVAL 10 SECOND AND p.opened_at + INTERVAL 5 SECOND WHERE p.id IN (182,172,162,158,143,137) ORDER BY o.executed_at LIMIT 12;